svg.script:
(function(){
  var root=document.documentElement, st='idle', tOpen=null, tTalk=null, tBlink=null;
  var TS={"collapsed":{"rig-ekor-pos":"translate(685, 855) scale(0.85, 0.85)"},"opening":{"rig-elbow-right":"translate(-436, 591.1) rotate(120.5)","rig-shoulder-right":"translate(-795, -295) rotate(-66) scale(0.97, 0.97)","hand-right-open":"translate(128.1, 711.6) rotate(200) scale(0.85, 0.85)","rig-elbow-left":"translate(503.7, 298) rotate(-40)"},"idle":{"rig-elbow-right":"translate(-436, 317) rotate(22)","rig-shoulder-right":"translate(-903.1, -273.7) rotate(-16) scale(0.97, 0.97)","rig-ear-left":"translate(905.9, -1002.6) scale(0.95, 0.95)","rig-ear-right":"translate(-773.4, -1107.2) rotate(4) scale(0.96, 0.96)"},"explaining":{},"pose1":{"rig-elbow-right":"translate(162.7, -267) rotate(33)","badan-kerah-dada-overlay":"translate(1847.7, 2533.5) scale(0.6, 0.6)","rig-badan":"translate(-1373, -1825.1) scale(0.31, 0.31)","rig-head-base":"translate(10.7, -932.5) scale(1.24, 1.22)","rig-shoulder-left":"translate(37.7, 205.3) rotate(28.5) scale(0.54, 0.54)","rig-shoulder-right":"translate(155.2, -47.3) rotate(-24) scale(0.97, 0.97)","rig-hip-bridge-stand":"translate(108.6, -77.9)","rig-calf-right-stand":"translate(-114.9, -33.9) scale(0.47, 0.47)","rig-calf-left-stand":"translate(266.1, 436.9) scale(0.47, 0.47)","rig-ekor-pos":"translate(974.1, 954.2) scale(0.85, 0.85)","rig-neck":"translate(49.9, 1176.9)","hand-right-fist-back":"translate(64.5, 720.9) rotate(133) scale(0.78, 0.78)","hand-left-fist-back":"translate(-67, 343) rotate(-140) scale(0.78, 0.78)","rig-elbow-left":"translate(-284.4, 453.5) rotate(-40)","rig-ear-left":"translate(857.3, -902.9) scale(0.95, 0.95)","rig-ear-right":"translate(-723, -880.7) rotate(4) scale(0.96, 0.96)","rig-nose":"translate(-218.7, -231.3) scale(1.42, 1.42)","rig-mouth":"translate(-288.3, -118.9)","rig-eyes":"translate(-114.1, -1029.9)","rona_pipi_kanan":"translate(-929.9, 27.9) scale(0.72, 0.72)","rona_pipi_kiri":"translate(550.1, 158.1) scale(0.72, 0.72)"}}, BASE={"rig-calf-right-stand":"translate(-445, 1255) scale(0.9, 0.9)","rig-calf-left-stand":"translate(485, 1225) scale(0.9, 0.9)","rig-hip-bridge-stand":"translate(0, 845)","rig-shoulder-right":"translate(-795, -295) rotate(-24) scale(0.97, 0.97)","rig-elbow-right":"translate(-416.9, 193.1) rotate(33)","hand-right-fist-back":"translate(63.9, 717.2) rotate(133) scale(0.78, 0.78)","hand-right-open":"translate(129.2, 769.7) rotate(200) scale(0.85, 0.85)","rig-shoulder-left":"translate(760, -340) rotate(28.5) scale(0.95, 0.95)","rig-elbow-left":"translate(561.7, 217.2) rotate(-40)","hand-left-fist-back":"translate(-4, 737.7) rotate(-140) scale(0.78, 0.78)","rig-ekor-pos":"translate(680, 860) scale(0.85, 0.85)","rig-ear-left":"translate(980, -1120) scale(0.95, 0.95)","rig-ear-right":"translate(-865, -1095) rotate(4) scale(0.96, 0.96)","badan-kerah-dada-overlay":"","rig-badan":"translate(-4691, -5868)","rig-head-base":"translate(0, -900) scale(1.24, 1.22)","rig-neck":"translate(0, -820)","rig-nose":"translate(0, -240) scale(1.42, 1.42)","rig-mouth":"translate(0, -135)","rig-eyes":"translate(0, -860)","rona_pipi_kanan":"translate(-690, 0) scale(0.72, 0.72)","rona_pipi_kiri":"translate(690, 0) scale(0.72, 0.72)"}, STATES=["collapsed","opening","idle","explaining","pose1"], PB={"collapsed":null,"opening":null,"idle":null,"explaining":null,"pose1":""}, VIS={"collapsed":{"mouth-open-group":false},"opening":{},"idle":{"mouth-open-group":false},"explaining":{},"pose1":{}};
  function applyPose(s){
    var seen={};
    Object.keys(BASE).forEach(function(i){seen[i]=1;});
    Object.keys(TS).forEach(function(k){Object.keys(TS[k]).forEach(function(i){seen[i]=1;});});
    Object.keys(seen).forEach(function(i){
      var el=q(i); if(!el)return;
      var v=(TS[s]&&TS[s][i]!==undefined)?TS[s][i]:BASE[i];
      if(v)el.setAttribute('transform',v); else el.removeAttribute('transform');
      if(VIS[s]&&VIS[s][i]===false){ el.style.display='none'; } else { el.style.display=''; }
    });
  }
  function q(i){return document.getElementById(i);}
  function mouth(o){ if(o) root.classList.add('mascot-mouth-open'); else root.classList.remove('mascot-mouth-open'); }
  function blink(){ root.classList.add('mascot-blinking'); setTimeout(function(){ root.classList.remove('mascot-blinking'); }, 130); }
  function talk(on){ if(tTalk){clearInterval(tTalk); tTalk=null;} if(on){var o=true; mouth(true); tTalk=setInterval(function(){o=!o; mouth(o);},165);} else mouth(false); }
  function setState(s){
    if(STATES.indexOf(s)<0) return;
    if(tOpen){clearTimeout(tOpen); tOpen=null;} talk(false); st=s;
    root.setAttribute('class','mascot-state-'+s); applyPose(s);
    var b=PB[s]||s;
    if(b==='opening'){ mouth(true); setTimeout(function(){mouth(false);},800); if(!PB[s]) tOpen=setTimeout(function(){setState('idle');},1250); }
    if(b==='explaining') talk(true);
  }
  function loopBlink(){ tBlink=setTimeout(function(){ blink(); loopBlink(); }, 2600+Math.random()*2800); }
  window.Mascot={setState:setState,getState:function(){return st;},blink:blink,talk:talk,states:STATES};
  window.addEventListener('message',function(e){var d=e.data||{}; if(d.mascotState)setState(d.mascotState); if(typeof d.mascotTalk==='boolean')talk(d.mascotTalk);});
  var defaultState = 'pose1';
  try {
    var params = new URLSearchParams(window.location.search);
    var qState = params.get('state');
    if(qState && STATES.indexOf(qState) >= 0) defaultState = qState;
  } catch(e){}
  loopBlink();
  setState(defaultState);
})();
